def recombine_sections(soup):
    """
    Iterates through the document's heading tags to segment the content 
    into distinct sections, using the heading text as the section title.
    """
    sections = []

    # Find all headings to use as section boundaries
    headings = soup.find_all('h1') + soup.find_all('h2', class_='slide-title') + soup.find_all('h3')

    if not headings:
        return "<!-- No major headings (h1, h2, h3) found to segment content. -->"

    # Get the body element
    body = soup.find('body')
    if not body:

        return "<!-- No body tag found -->"

    # Helper function to collect all descendants up to a stopping point
    def collect_up_to(stop_node, start_node):
        """Collect nodes from start_node until (but not including) stop_node."""
        if hasattr(start_node, 'parent'):
            parent = start_node.parent
            collected = []
            to_visit = [start_node]

            while to_visit and parent is not None:
                # Process current level
                if parent in to_visit and parent is stop_node:
                    break

                for node_obj in to_visit:
                    collected.append(node_obj)

                    if hasattr(node_obj, 'children'):
                        try:
                            # Recursively collect children, stopping at stop_node
                            child_to_visit = []
                            for child in node_obj.children:
                                if child is stop_node:
                                    return "\n".join([str(n) for n in collected])
                                child_to_visit.append(child)
                        except:
                            pass
                        to_visit = child_to_visit

                try:
                    parent = parent.parent
                except:
                    break

        return "\n".join([str(n) for n in collected])

    # Loop through all headings to define section boundaries
    for i, heading in enumerate(headings):
        title = heading.get_text(strip=True)

        # Determine the end point for the content block
        # If there is a next heading, the content ends right before it.
        if i + 1 < len(headings):
            end_tag = headings[i+1]
        # If this is the last heading, the content runs until the end of the body
        else:
            end_tag = body

        # Extract content from this heading down to the next heading (or body end)
        content_list = []
        to_visit = [heading]
        to_check = [body] if end_tag is body else [end_tag]
        to_visit.extend(to_check) if end_tag in to_check.to_check else to_check[0:0]  # no-op

        current = heading
        while current and hasattr(current, 'parent'):
            collected_so_far = []
            current = current
            try:
                if end_tag and current == end_tag:
                    break
            except:
                pass

            if hasattr(current, 'children'):
                children_list = list(current.children)
                content_list.extend(children_list)
                if len(children_list) > 0:
                    # Check if we've passed end_tag
                    pass

            try:
                content_list.append(current)
            except:
                pass

            try:
                parent = current.parent
                if parent is end_tag:
                    break
                current = parent
            except:
                current = None

        content_str = "\n".join([str(node) for node in content_list if hasattr(node, '__str__')])

        sections.append({'title': title, 'content': content_str})

    # Reconstruct the HTML for better structural output
    rearranged_html_parts = []
    for section in sections:
        title = section['title']
        content = section['content']
        # Use a class name for styling consistency in the slide presentation
        rearranged_html_parts.append(f'<section class="section-container"><h3 class="slide-title">{title}</h3><div class="section-content">{content}</div></section>')

    return "\n".join(rearranged_html_parts)

