def flatten_tree(element):
    """Recursively flatten an element and all its children into a list.
    Only includes tags, not text nodes.
    """
    result = []
    try:
        for child in element.children:
            if hasattr(child, 'name'):
                # It's a tag, add it
                result.append(child)
                # Recursively add its children
                result.extend(flatten_tree(child))
            elif child.strip():
                # It's text, skip it
                pass
    except AttributeError:
        # Element has no children (e.g., NavigableString), skip
        pass
    return result
